1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  EmbeddedEventDetails_Tags,
4	  type EventTimelineItem,
5	  type MediaSourceInterface,
6	  MessageType_Tags,
7	  MsgLikeKind_Tags,
8	  ProfileDetails_Tags,
9	  TimelineItemContent_Tags,
10	} from "@unomed/react-native-matrix-sdk";
11	import { useSetAtom } from "jotai";
12	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
13	import {
14	  cleanMentions,
15	  getEventTextContent,
16	  getMessageTextContent,
17	} from "modules/matrix-client/utils";
18	import { TimelineAtoms } from "modules/timeline/jotai";
19	import { TimelineService } from "modules/timeline/service/TimelineService";
20	import { type FC, useCallback, useEffect, useMemo, useState } from "react";
21	import { Dimensions, Image, StyleSheet } from "react-native";
22	import { MessageTimestamp, PinIndicator, SeenBy } from "shared/components";
23	import { Colors, TextSize } from "shared/styles";
24	import { MentionText } from "../mention-text";
25	import { MessageLongPressWrapper } from "../message-long-press-wrapper";
26	import { MessageSender } from "../message-sender";
27	import { ReplyPayload } from "../reply-paylaod";
28	
29	interface Props {
30	  event: EventTimelineItem;
31	  isPreviousSameSender: boolean;
32	  onMemberPress?: (member: MemberDetailsPayload) => void;
33	}
34	
35	const { width } = Dimensions.get("window");
36	
37	// Parse <a href="https://matrix.to/#/@user:server">@DisplayName</a> tags from
38	// formatted_body HTML into a lowercase-displayName → userId map.
39	// This is the sync fast path — no profile loading needed.
40	const parseMentionMapFromHtml = (html: string): Map<string, string> => {
41	  const regex =
42	    /<a[^>]+href="https:\/\/matrix\.to\/#\/(@[^"]+)"[^>]*>@?([^<]+)<\/a>/gi;
43	  const matches = Array.from(html.matchAll(regex));
44	  return new Map(matches.map((m) => [m[2].toLowerCase(), m[1]]));
45	};
46	
47	export const TextMessage: FC<Props> = ({
48	  event,
49	  isPreviousSameSender,
50	  onMemberPress,
51	}) => {
52	  const [messageWidth, setMessageWidth] = useState(116);
53	  const isUser = event.isOwn;
54	  const sender = event.senderProfile;
55	  const senderId = event.sender;
56	  const seenByUserIds = TimelineService.getReadReceiptUserIds(event);
57	  const [mentionMap, setMentionMap] = useState<Map<string, string>>(new Map());
58	  // Some clients (Element X) put raw markdown links in the body:
59	  // [@Name](matrix.to/#/@user:server)  — link text has @
60	  // [Name](matrix.to/#/@user:server)   — link text without @
61	  // Detect by the /#/@ pattern in the URL (user permalink) and normalize to @Name.
62	  const content = cleanMentions(getEventTextContent(event));
63	  const maxWidth = width - 60;
64	  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);
65	
66	  const { formattedBody, mentionUserIds, isEdited } = useMemo(() => {
67	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike)
68	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
69	    const kind = event.content.inner.content.kind;
70	    if (kind?.tag !== MsgLikeKind_Tags.Message) {
71	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
72	    }
73	    const msgType = kind.inner.content.msgType;
74	    const html =
75	      msgType?.tag === MessageType_Tags.Text
76	        ? msgType.inner.content.formatted?.body
77	        : undefined;
78	    return {
79	      formattedBody: html,
80	      mentionUserIds: kind.inner.content.mentions?.userIds ?? [],
81	      isEdited: kind.inner.content.isEdited,
82	    };
83	  }, [event]);
84	
85	  useEffect(() => {
86	    // Fast path: extract mention map directly from formatted_body HTML
87	    if (formattedBody) {
88	      const map = parseMentionMapFromHtml(formattedBody);
89	      if (map.size > 0) {
90	        setMentionMap(map);
91	        return;
92	      }
93	    }
94	
95	    // Fallback: load profiles for mentioned user IDs (messages without formatted_body)
96	    if (!mentionUserIds.length) return;
97	    const client = MatrixCore.getClient();
98	    Promise.allSettled(mentionUserIds.map((id) => client.getProfile(id))).then(
99	      (results) => {
100	        const map = new Map<string, string>();
101	        results.forEach((result, i) => {
102	          const userId = mentionUserIds[i];
103	          const displayName =
104	            result.status === "fulfilled"
105	              ? (result.value.displayName ?? userId)
106	              : userId;
107	          map.set(displayName.toLowerCase(), userId);
108	        });
109	        setMentionMap(map);
110	      },
111	    );
112	  }, [formattedBody, mentionUserIds]);
113	
114	  const replyPayload = useMemo(() => {
115	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;
116	
117	    const inReplyTo = event.content.inner.content.inReplyTo;
118	
119	    if (!inReplyTo) return null;
120	
121	    const eventDetails = inReplyTo.event();
122	    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;
123	
124	    const senderName =
125	      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
126	        ? (eventDetails.inner.senderProfile.inner.displayName ??
127	          eventDetails.inner.sender)
128	        : eventDetails.inner.sender;
129	
130	    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
131	      null;
132	    const replyContent = eventDetails.inner.content;
133	
134	    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
135	      const kind = replyContent.inner.content.kind;
136	      if (kind?.tag === MsgLikeKind_Tags.Message) {
137	        const msgType = kind.inner.content.msgType;
138	        if (msgType?.tag === MessageType_Tags.Image) {
139	          mediaSource = {
140	            source: msgType.inner.content.source,
141	            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
142	          };
143	        }
144	        if (msgType?.tag === MessageType_Tags.Video) {
145	          mediaSource = {
146	            source: msgType.inner.content.source,
147	            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
148	          };
149	        }
150	      }
151	    }
152	
153	    return {
154	      eventId: inReplyTo.eventId(),
155	      senderName,
156	      content: getMessageTextContent(eventDetails.inner.content),
157	      mediaSource,
158	    };
159	  }, [event]);
160	
161	  const handleReplyPress = useCallback(() => {
162	    if (replyPayload) setScrollToEventId(replyPayload.eventId);
163	  }, [replyPayload, setScrollToEventId]);
164	
165	  return (
166	    <Block
167	      align={isUser ? "flex-end" : "flex-start"}
168	      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
169	    >
170	      <MessageSender
171	        sender={sender}
172	        senderId={senderId}
173	        isUser={isUser}
174	        isPreviousSameSender={isPreviousSameSender}
175	        onMemberPress={onMemberPress}
176	      />
177	      <MessageLongPressWrapper event={event} content={content}>
178	        <Block flexDirection={isUser ? "row-reverse" : "row"}>
179	          <Block
180	            paddings={12}
181	            background={isUser ? Colors.primary : Colors.message}
182	            border={{ borderRadius: 24 }}
183	            align="stretch"
184	            gap={12}
185	            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
186	            maxWidth={maxWidth}
187	          >
188	            <ReplyPayload
189	              replyPayload={replyPayload}
190	              onPress={handleReplyPress}
191	            />
192	            <Block
193	              justify="space-between"
194	              align="center"
195	              flex={{ flexWrap: "wrap" }}
196	              flexDirection={isUser ? "row-reverse" : "row"}
197	              gap={{
198	                row: 4,
199	                col: 16,
200	              }}
201	              // Some short strings (e.ag., "aa", "ai") wrap unexpectedly, while others ("dd", "a") do not.
202	              // Add this value to prevent unwanted wrapping for short text.
203	              minWidth={116}
204	            >
205	              {mentionMap.size > 0 ? (
206	                <MentionText
207	                  isUser={isUser}
208	                  body={content}
209	                  mentionMap={mentionMap}
210	                  onMentionPress={onMemberPress}
211	                />
212	              ) : (
213	                <Text size={TextSize.small} color="white">
214	                  {content}
215	                </Text>
216	              )}
217	              <MessageTimestamp
218	                event={event}
219	                isUser={isUser}
220	                isEdited={isEdited}
221	              />
222	            </Block>
223	            {isPreviousSameSender && (
224	              <Block
225	                absolute
226	                offsets={
227	                  isUser
228	                    ? {
229	                        right: 6,
230	                        bottom: 2,
231	                      }
232	                    : {
233	                        left: 6,
234	                        bottom: 2,
235	                      }
236	                }
237	              >
238	                <Image
239	                  source={
240	                    isUser
241	                      ? require("assets/icons/polygon.png")
242	                      : require("assets/icons/guest-polygon.png")
243	                  }
244	                  width={7}
245	                  height={6}
246	                  style={styles.polygon}
247	                />
248	              </Block>
249	            )}
250	          </Block>
251	          <PinIndicator event={event} />
252	        </Block>
253	      </MessageLongPressWrapper>
254	      <SeenBy userIds={seenByUserIds} messageWidth={messageWidth} />
255	    </Block>
256	  );
257	};
258	
259	const styles = StyleSheet.create({
260	  polygon: {
261	    width: 7,
262	    height: 6,
263	  },
264	});
