1	import ReactNativeBlobUtil from "react-native-blob-util";
2	
3	//TODO: Add encryption for cached images
4	
5	const CacheDir = `${ReactNativeBlobUtil.fs.dirs.CacheDir}/images`;
6	const PrefixlessCacheDir = CacheDir.replace("file://", "");
7	const CurrentBatch = new Map<string, Promise<void>>();
8	let CacheDirReady = false;
9	
10	function getFilenameByURL(url: string) {
11	  let hash = 0;
12	  for (let i = 0; i < url.length; i++) {
13	    hash = (hash << 5) - hash + url.charCodeAt(i);
14	    hash |= 0; // Convert to 32bit integer
15	  }
16	  return (hash >>> 0).toString(36);
17	}
18	
19	/** Returns storage filename associated with provided URL, including the file:// prefix */
20	export function getCachedImagePathByURL(url: string) {
21	  const fileName = getFilenameByURL(url);
22	  // Ensure the base CacheDir is just a path, not prefixed, before joining.
23	  // Then add the file:// prefix at the end.
24	  return `file://${PrefixlessCacheDir}/${fileName}`;
25	}
26	
27	function getStoragePathByUrl(url: string) {
28	  const fileName = getFilenameByURL(url);
29	  return `${PrefixlessCacheDir}/${fileName}`;
30	}
31	
32	async function downloadToPath(url: string, localFilePath: string) {
33	  const responseRaw = await ReactNativeBlobUtil.config({
34	    path: localFilePath,
35	  }).fetch("GET", url);
36	
37	  const response = responseRaw.info();
38	  const status = response.status;
39	
40	  if (status < 200 || status >= 300) {
41	    // Remove invalid cached file
42	    await ReactNativeBlobUtil.fs.unlink(localFilePath);
43	    throw new Error(`Unable to cache ${url}, http ${status}`);
44	  }
45	}
46	
47	async function ensureCached(
48	  cacheKey: string,
49	  downloadUrl: string,
50	): Promise<void> {
51	  if (CurrentBatch.has(cacheKey)) {
52	    return CurrentBatch.get(cacheKey);
53	  }
54	
55	  const localFilePath = getStoragePathByUrl(cacheKey);
56	  const cachingPromise = (async () => {
57	    try {
58	      if (!CacheDirReady) {
59	        const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
60	        if (!dirExists) await ReactNativeBlobUtil.fs.mkdir(CacheDir);
61	        CacheDirReady = true;
62	      }
63	
64	      const fileExists = await ReactNativeBlobUtil.fs.exists(localFilePath);
65	      if (!fileExists) {
66	        await downloadToPath(downloadUrl, localFilePath);
67	      } else {
68	        const stat = await ReactNativeBlobUtil.fs.stat(localFilePath);
69	        if (!stat || stat.size === 0) {
70	          await ReactNativeBlobUtil.fs.unlink(localFilePath);
71	          await downloadToPath(downloadUrl, localFilePath);
72	        }
73	      }
74	    } catch (error) {
75	      console.warn(
76	        `Failed to cache image ${downloadUrl} to ${localFilePath}:`,
77	        error,
78	      );
79	    } finally {
80	      CurrentBatch.delete(cacheKey);
81	    }
82	  })();
83	
84	  CurrentBatch.set(cacheKey, cachingPromise);
85	  return cachingPromise;
86	}
87	
88	/** Returns true if the image for the given URL is already cached on disk. */
89	export async function isCached(url: string): Promise<boolean> {
90	  const localFilePath = getStoragePathByUrl(url);
91	  try {
92	    const fileExists = await ReactNativeBlobUtil.fs.exists(localFilePath);
93	    if (!fileExists) return false;
94	    const stat = await ReactNativeBlobUtil.fs.stat(localFilePath);
95	    return !!stat && stat.size > 0;
96	  } catch {
97	    return false;
98	  }
99	}
100	
101	/**
102	 * Caches downloaded image and returns a Promise that resolves when the image is fully written.
103	 * Handles concurrent requests for the same URL.
104	 */
105	export async function cacheImage(url: string): Promise<void> {
106	  return ensureCached(url, url);
107	}
108	
109	/**
110	 * Caches an image using `cacheKey` as the cache identifier (e.g. MXC URL)
111	 * but downloads from `downloadUrl` (e.g. authenticated HTTP URL).
112	 */
113	export async function cacheImageWithKey(
114	  cacheKey: string,
115	  downloadUrl: string,
116	): Promise<void> {
117	  return ensureCached(cacheKey, downloadUrl);
118	}
119	
120	/** Removes all cached images from disk. Call on logout. */
121	export async function clearImageCache(): Promise<void> {
122	  try {
123	    const dirExists = await ReactNativeBlobUtil.fs.exists(CacheDir);
124	    if (dirExists) {
125	      await ReactNativeBlobUtil.fs.unlink(CacheDir);
126	    }
127	  } catch (error) {
128	    console.warn("Failed to clear image cache:", error);
129	  } finally {
130	    CacheDirReady = false;
131	    CurrentBatch.clear();
132	  }
133	}
